update_rule.pseudocode:
for each individual i:
  N_i = neighbors(i)
  if |N_i| == 0: share = 0
  else share = mean(adoption_state[j] for j in N_i)
  # optional exponential smoothing via forgetting_rate
  signal.neighbor_mask_share[i] = (1 - forgetting_rate) * prev_share[i] + forgetting_rate * share

if t == 0:
  mandate = mandate_active_initial
else:
  if mandate == false and observable.adoption_rate_daily[t-1] < activation_threshold and signal.risk_today > 0.4:
    mandate = true
  elif mandate == true and observable.adoption_rate_daily[t-1] > deactivation_threshold and signal.risk_today < 0.3:
    mandate = false
# enforcement probability baseline scaled
p_enforce = clip(enforcement_probability_base * (1 + 0.5*(signal.risk_today - 0.5)), 0, 1)
emit policy.mandate_active = mandate
emit policy.enforcement_probability = p_enforce
emit policy.subsidy_amount = subsidy_amount
emit policy.fine_amount = fine_amount

enforcement_actions = 0; denied_entries = 0
for each individual i:
  num_visits ~ Poisson(daily_visits_mean)
  for v in 1..num_visits:
    choose location L ~ weighted by type preference and capacity
    require_mask = L.mask_policy or policy.mandate_active
    if require_mask and adoption_state[i] == 0:
      if Bernoulli(policy.enforcement_probability * enforcement_probability_location_multiplier) == 1:
        enforcement_actions += 1
      # entry policy
      if L.mask_policy:
        denied_entries += 1  # denied entry for noncompliance where local policy exists
emit logs
